'use server'

import { updateTag } from 'next/cache'

export async function createPost(formData: FormData) {
  const title = formData.get('title')
  const content = formData.get('content')

  const post = {
    title,
    content,
  }

  // Expire the posts tag immediately so the next read waits for fresh data
  // instead of serving stale cached content (read-your-writes).
  updateTag('posts')

  return post
}

